      hu: ["Nem az Appalache-hegység része.", "Számtalan tó és erdő.", "Nagy védett természeti terület.", "Népszerű kenu-túrákhoz.", "Magas gránithegyek.", "Népszerű célpont nyáron és télen."],
      ro: ["Nu face parte din Munții Apalași.", "Nenumărate lacuri și păduri.", "Zonă naturală protejată mare.", "Popular pentru canotaj.", "Munți înalți de granit.", "Destinație populară vara și iarna."],
      en: ["Not part of the Appalachians.", "Countless lakes and forests.", "Large protected natural area.", "Popular for canoeing.", "High granite mountains.", "Popular destination in summer and winter."],
      es: ["No forman parte de los Apalaches.", "Innumerables lagos y bosques.", "Gran área natural protegida.", "Popular para excursiones en canoa.", "Altas montañas de granito.", "Destino popular en verano e invierno."],
      pt: ["Não fazem parte dos Apalaches.", "Inumeráveis lagos e florestas.", "Grande área natural protegida.", "Popular para excursões de canoa.", "Montanhas altas de granito.", "Destino popular no verão e no inverno."],
      fr: ["Ne font pas partie des Appalaches.", "D'innombrables lacs et forêts.", "Grande zone naturelle protégée.", "Populaire pour les randonnées en canoë.", "Hautes montagnes de granit.", "Destination populaire en été comme en hiver."],
